#!/usr/bin/env bash
# setup_deps.sh — generated by gen_setup_deps.py
# Task: build-cython-ext
# Base image: python:3.13-slim-bookworm
#
# Sets up the task workspace at $WORKDIR (default: /app).
# TB_ROOT points at the terminal-bench-2 checkout.
#
# Usage:
#   [TB_ROOT=~/z2/terminal-bench-2] [WORKDIR=/app] bash setup_deps.sh

set -euo pipefail

TB_ROOT="${TB_ROOT:-$HOME/z2/terminal-bench-2}"
TASK_ENV="$TB_ROOT/build-cython-ext/environment"
WORKDIR="${WORKDIR:-/app}"

# ── source common base tooling ──────────────────────────────────────────────
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BASE_SCRIPT="$(dirname "$(dirname "$SCRIPT_DIR")")/setup_base.sh"
if [[ -f "$BASE_SCRIPT" ]]; then
  # shellcheck source=/dev/null
  source "$BASE_SCRIPT"
fi

mkdir -p "$WORKDIR"

# (no ENV directives)
# ── system packages ─────────────────────────────────────────────────────────
# Set SKIP_APT=1 when packages are pre-installed on the host (runner sets this)
if [[ -z "${SKIP_APT:-}" ]]; then
  sudo apt-get update -qq
  sudo apt-get install -y --no-install-recommends \
    build-essential git libgl1-mesa-glx
  sudo rm -rf /var/lib/apt/lists/*
fi
# (no COPY directives)
# ── per-task Python packages (isolated venv via uv) ─────────────────────────
command -v uv >/dev/null 2>&1 || curl -LsSf https://astral.sh/uv/install.sh | sh
uv venv --python python3 "$WORKDIR/.venv" 2>/dev/null || true
# shellcheck source=/dev/null
source "$WORKDIR/.venv/bin/activate"
uv pip install "numpy==2.3.0"
# (no unclassified RUN directives)
echo "[setup_deps] build-cython-ext ready — workspace: $WORKDIR"
